CH = [
 ("peter", "Peter Culberson, Union cavalryman", "Ada's grandfather Peter Culberson (1833 to 1914) rode with Company F of the 3rd Tennessee Cavalry, was held at Cahaba, and came home to McMinn County. His widow drew his pension."),
 ("tippens", "The Tippens", "Mary Tennessee Culberson was born a Tippens: William Henry Tippens and Eliza Owens married in McMinn County in 1867. These are her people."),
 ("bill", "Bill and Mary Culberson", "William L. \"Bill\" Culberson (1867 to 1965) and Mary Tennessee Tippens (1873 to 1955), Ada's parents, in Polk County, Tennessee: from the 1902 family group to the funeral in 1955."),
 ("ada", "Ada and Chester Moss", "Ada Nellie Culberson married Chester Ray Moss of Delano. Their daughter Joy married Buster Kirkland and moved to Detroit; Joy's daughter was Glenda, your grandmother."),
 ("siblings", "Ada's brothers and sisters", "Callie, Claude, Bob, Joe, Beulah, Charlie and the rest of Bill and Mary's children, with their husbands, wives and children: the Culberson aunts and uncles."),
 ("charlie", "Charlie and Elizabeth's family", "Ada's youngest brother Charlie (1912 to 2001) married Ida Elizabeth Martin (1914 to 1994). Their sons Ron, Larry, David and Mike kept the family's pictures and put them online, which is where most of this album comes from."),
 ("martin", "Elizabeth's people: Martins, Brashers and Redwines", "Elizabeth's own family, through her mother Etta Luticia Brasher, an evangelist of the Methodist Episcopal Church, and her father Nelson Martin, who died when she was two. Family by marriage: no blood tie to your line, kept because they are part of the same albums."),
 ("kirkland", "Kirkland and Bivens", "Stones from Antioch Cemetery, Tennessee, on the Kirkland and Bivens side."),
 ("pavia", "Pavia and Termenas", "The northern side: the Pavias of Malta and Detroit, and Joseph Termenas's crossing to France in 1917."),
 ("papers", "Papers", "Newspaper columns, certificates and abstracts that came with the pictures."),
]
